mapper.sql:
SELECT MIN(row_id) AS row_id, accrual_id, MIN(NULLIF(TRIM(product_name), '')) AS product_name, MIN(accrual_date) AS first_accrual_date, MAX(accrual_date) AS accrual_date, SUM(CASE WHEN total_amount_rub > 0 THEN total_amount_rub ELSE 0 END) AS positive_amount_rub, SUM(CASE WHEN total_amount_rub < 0 THEN total_amount_rub ELSE 0 END) AS negative_amount_rub, SUM(total_amount_rub) AS total_amount_rub, (SUM(total_amount_rub) - SUM(CASE WHEN total_amount_rub > 0 THEN total_amount_rub ELSE 0 END) * 0.075) AS after_tax_amount_rub, (SUM(total_amount_rub) - SUM(CASE WHEN total_amount_rub > 0 THEN total_amount_rub ELSE 0 END) * 0.075) * 0.075 AS total_amount_cny, COUNT(*) AS record_count FROM ozon_accruals
accrual_id IS NOT NULL AND TRIM(accrual_id) <> ''
AND accrual_id = #{q.accrualId}
GROUP BY accrual_id
AND MAX(accrual_date) >= #{q.startDate} AND MAX(accrual_date) <= #{q.endDate}

SELECT MIN(a.row_id) AS row_id, AS product_key, COALESCE(MAX(NULLIF(TRIM(a.product_name), '')), '未标注商品') AS product_name, MAX(NULLIF(TRIM(a.seller_sku), '')) AS seller_sku, a.accrual_id, COALESCE(MIN(CASE WHEN a.accrual_type = '销售收入' THEN a.order_accepted_or_service_date END), MIN(a.order_accepted_or_service_date), MIN(a.accrual_date)) AS sale_date, MAX(a.accrual_date) AS accrual_date, SUM(a.total_amount_rub) AS sales_amount_rub FROM ozon_accruals a INNER JOIN () s ON s.accrual_id = a.accrual_id WHERE a.total_amount_rub > 0 AND s.total_amount_rub <> 0
AND = #{q.productKey}
GROUP BY product_key, a.accrual_id
